app.MapPost("/orders/{id:int}/cancel", async (
    int id, ClaimsPrincipal user, ShopDb db, IPayments payments) =>
{
    // Logged in, owner checked, parameterized by EF Core: no findings
    var order = await db.Orders.SingleOrDefaultAsync(
        o => o.Id == id && o.CustomerId == user.FindFirstValue("sub"));
    if (order is null) return Results.NotFound();

    await payments.RefundAsync(order.Id, order.Total); // on every call
    order.Status = OrderStatus.Cancelled;
