app.MapPost("/orders/{id:int}/cancel", async (
    int id, ClaimsPrincipal user, ShopDb db, IPayments payments) =>
{
    var order = await db.Orders.SingleOrDefaultAsync(
        o => o.Id == id && o.CustomerId == user.FindFirstValue("sub"));
    if (order is null) return Results.NotFound();

    // The design rule: only a paid, unshipped order can be cancelled
    if (order.Status != OrderStatus.Paid) return Results.Conflict();

    order.Status = OrderStatus.Cancelled;
    await db.SaveChangesAsync(); // a concurrency token stops a parallel cancel
    await payments.RefundAsync(order.Id, order.Total);
    return Results.NoContent();
}).RequireAuthorization();
